  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 8px;
  padding: 16px 28px;
}
li {
  color: #6B5A4E;
  margin: 6px 0;
  font-family: 'Fira Code', monospace;
  font-size: 14px;
}
